//! Facts about built-in kinds taken from the Kubernetes schema kustomize embeds
//! (`src/schema/*.json`, generated by `scripts/import-upstream.sh`).

use std::collections::HashMap;
use std::sync::OnceLock;

use serde::Deserialize;

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct ScopeEntry {
    api_version: String,
    kind: String,
    namespaced: bool,
}

fn namespace_scope() -> &'static HashMap<(String, String), bool> {
    static TABLE: OnceLock<HashMap<(String, String), bool>> = OnceLock::new();
    TABLE.get_or_init(|| {
        // Embedded and checked by a unit test, so a parse failure can't ship.
        let entries: Vec<ScopeEntry> =
            serde_json::from_str(include_str!("schema/namespace-scope.json")).unwrap_or_default();
        entries
            .into_iter()
            .map(|e| ((e.api_version, e.kind), e.namespaced))
            .collect()
    })
}

/// Whether a kind is namespaced, if the built-in schema knows it.
pub fn is_namespaced(api_version: &str, kind: &str) -> Option<bool> {
    namespace_scope()
        .get(&(api_version.to_string(), kind.to_string()))
        .copied()
}

/// Whether a kind is known to be cluster-scoped (kyaml's
/// `IsCertainlyClusterScoped`). Unknown kinds, such as custom resources, count
/// as namespaced.
pub fn is_cluster_scoped(api_version: &str, kind: &str) -> bool {
    is_namespaced(api_version, kind) == Some(false)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn embedded_table_parses() {
        assert!(
            namespace_scope().len() > 50,
            "namespace-scope.json failed to load"
        );
    }

    #[test]
    fn cluster_scope_follows_the_table_and_unknown_kinds_are_namespaced() {
        assert!(is_cluster_scoped("v1", "Namespace"));
        assert!(is_cluster_scoped(
            "rbac.authorization.k8s.io/v1",
            "ClusterRole"
        ));
        assert!(!is_cluster_scoped("v1", "ConfigMap"));
        assert!(!is_cluster_scoped("example.com/v1", "Widget"));
        assert_eq!(is_namespaced("example.com/v1", "Widget"), None);
    }
}
